{
 "topic": "Types of Fractions",
 "affirmation": "You used shapes and cake stories to make fractions feel real.",
 "identity": "You teach with warm, concrete pictures: circles, rectangles, and the cake story appeared again and again to carry the math. You name the vocabulary aloud, repeat student words, and invite short explanations so the room stays lively and safe for trying.",
 "moments": [
  {
   "title": "Identifying the shape",
   "quote": "یہ سرکل ہے۔",
   "why": "That quick student label anchored the whole lesson and let you pivot from 'shape' to 'parts' instantly."
  },
  {
   "title": "Student fraction attempt",
   "quote": "10 میں سے 9، 9، 10 میں سے 1 گئے تو 9 بچ گیا۔ 9 اور 10 نیچے، اور 9 اوپر۔",
   "why": "This muddled-but-trying explanation showed students were reaching for fraction notation and gave you a clear opening to clarify placement."
  },
  {
   "title": "Cake for meaning",
   "quote": "پارٹس اس لیے لاتے ہیں اور ایکول پارٹ لاتے ہیں تاکہ اس میں لائن نہ آئے۔",
   "why": "Your cake example tied the idea of equal parts to fairness, which made an abstract idea feel lived-in and relevant."
  }
 ],
 "strength_name": "Warm student engagement",
 "strength_note": "Students spoke often and used target words (naming shapes and vocabulary like 'نمبریٹر' and 'ڈینومینیٹر'), showing you created a talking, participatory classroom.",
 "horizon_title": "Specific next-step feedback",
 "horizon_note": "After a student's answer, add a brief corrective or 'do this next' line—one clear phrase that fixes the confusion and points the student forward.",
 "journey_note": "In this lesson you peaked at 68% and repeatedly returned to visual models and everyday examples to hold the class together.",
 "score_framing": "A 68% moment is a clear step in progress — your strong routines are present and ready to be sharpened with precise feedback.",
 "domain_whys": {
  "high_leverage_practices": "This was developing because you prompted many answers and used praise and naming in the moment (for example, calling out 'نمبریٹر' and saying 'شاباش') — it was not full marks because feedback stayed general and did not include specific corrective comments or short next steps after unclear responses.",
  "student_engagement": "This was strong because students used the lesson vocabulary and described the models ('یہ سرکل ہے', 'جو کلر کیا ہوا ہے، وہ اوپر ہے') — it was not full marks because student-initiated, content-focused questions were not observed and exchanges remained mainly teacher-led with brief student replies.",
  "teacher_subject_knowledge": "This was developing because you corrected muddled fraction notation and checked placement with students (for example, confirming that 9 is written above and 10 below) — it was not full marks because you did not press for extended mathematical explanations or explicitly name the common confusion between numerator and denominator."
 }
}
